// ===========================================================================
//  TEST CASES  —  POST /schools/current/academic-years
//  Needs the X-School-Subdomain header. Run Create School first.
// ===========================================================================
//
//  THE NAME CAN NEVER BE CHANGED. There is no rename endpoint and there must
//  never be one. Other collections do not reference a year by id — they store
//  this string in their own academicYear field. FeeInvoice, TransportTrip,
//  FeedbackCampaign, FacilityInspection and dozens more. "2026-2027" IS the
//  join key, so a rename would orphan all of them silently and every row would
//  still look valid.
//
// ---------------------------------------------------------------------------
// 01  CREATE WITH A CALENDAR                              -> 201 Created
//     The body above.
//     OUT: durationDays: 365, current: true, holidayCount: 2
//     Header: Location: /schools/current/academic-years/2026-2027
//
//     holidays are optional — omit the array and add them later via #20-#23.
// ---------------------------------------------------------------------------
//
// 02  DUPLICATE NAME                                  -> 409 Conflict
//     Send case 01 again.
//     OUT: { "code": "ACADEMIC_YEAR_NAME_TAKEN" }
// ---------------------------------------------------------------------------
//
// 03  OVERLAPPING DATES                               -> 409 Conflict
// {
//   "name": "2027-2028",
//   "startDate": "2027-03-01",
//   "endDate": "2028-02-28"
// }
//     OUT: { "code": "ACADEMIC_YEAR_OVERLAP",
//            "message": "These dates overlap '2026-2027' (...)" }
//
//     Two years covering one day would give every "which year is this?" lookup
//     two answers — and AcademicYear deliberately has NO current flag, so the
//     dates are the only thing that can answer it.
// ---------------------------------------------------------------------------
//
// 04  ADJACENT, NOT OVERLAPPING                           -> 201 Created
// {
//   "name": "2027-2028",
//   "startDate": "2027-04-01",
//   "endDate": "2028-03-31"
// }
//     Ends 03-31, next starts 04-01. Allowed — the check is "one ends before
//     the other starts", not four date comparisons.
// ---------------------------------------------------------------------------
//
// 05  BACKWARDS DATES                                -> 400 Bad Request
// {
//   "name": "bad-1",
//   "startDate": "2030-04-01",
//   "endDate": "2029-04-01"
// }
//     OUT: { "code": "INVALID_DATE_RANGE" }
// ---------------------------------------------------------------------------
//
// 06  A THREE-DAY "YEAR"                             -> 400 Bad Request
// {
//   "name": "bad-2",
//   "startDate": "2030-04-01",
//   "endDate": "2030-04-03"
// }
//     OUT: { "code": "IMPLAUSIBLE_DATE_RANGE" }
//     Accepted range is 30 to 800 days. Outside that it is a typo, not a
//     calendar.
// ---------------------------------------------------------------------------
//
// 07  HOLIDAY OUTSIDE THE YEAR                       -> 400 Bad Request
// {
//   "name": "bad-3",
//   "startDate": "2030-04-01",
//   "endDate": "2031-03-31",
//   "holidays": [ { "name": "Stray", "type": "FESTIVAL", "date": "2029-01-01" } ]
// }
//     OUT: { "code": "HOLIDAY_OUTSIDE_YEAR" }
// ---------------------------------------------------------------------------
//
// 08  TWO HOLIDAYS ON ONE DATE                       -> 400 Bad Request
// {
//   "name": "bad-4",
//   "startDate": "2030-04-01",
//   "endDate": "2031-03-31",
//   "holidays": [
//     { "name": "A", "type": "FESTIVAL", "date": "2030-11-08" },
//     { "name": "B", "type": "FESTIVAL", "date": "2030-11-08" }
//   ]
// }
//     OUT: { "code": "DUPLICATE_HOLIDAY_DATE" }
// ---------------------------------------------------------------------------
//
//  HolidayType: WEEKLY_OFF | PUBLIC_HOLIDAY | FESTIVAL | RELIGIOUS |
//               SCHOOL_EVENT | VACATION | EXAM_BREAK
//
//  Every non-working day is a DATED entry, including a weekly off. There is no
//  "weekly off day" setting anywhere in this system: schools here may run on
//  Sunday with the off day on any other weekday, so nothing may infer a closure
//  from the day of the week. That is why a year needs ~52 WEEKLY_OFF rows and
//  why #23 generate-weekly-off exists.
// ---------------------------------------------------------------------------

